package net.minecraft.nbt; import java.util.*; public class CompoundTag {public Map<String,Object>data=new HashMap<>();public CompoundTag getCompound(String k){return (CompoundTag)data.getOrDefault(k,new CompoundTag());}public void put(String k,Object v){data.put(k,v);}public void putIntArray(String k,int[]v){data.put(k,v.clone());}public int[]getIntArray(String k){return ((int[])data.getOrDefault(k,new int[0])).clone();}public void putByteArray(String k,byte[]v){data.put(k,v.clone());}public byte[]getByteArray(String k){return ((byte[])data.getOrDefault(k,new byte[0])).clone();}public void putInt(String k,int v){data.put(k,v);}public int getInt(String k){return (int)data.getOrDefault(k,0);}}